action.query:
query ($id: String!){
  assetGroupDesignAssetDesign(where: {assetGroupDesignId: {_eq: $id}}) {
    total
    edges {
      node {
        id
      }
    }
  }
}

action.mutation:
mutation UpdateAssetDesign($payload: [AssetDesignUpdatePayloadInput!]!) {
  mutation: updateAssetDesign(payload: $payload) { 
    id
    name
  }
}

mutation CreateAssetGroupDesign($payload: [AssetGroupDesignCreatePayloadInput!]!) {
  mutation: createAssetGroupDesign(payload: $payload) { 
    id
    number
  }
}

mutation CreateAssetDesign($payload: [AssetDesignCreatePayloadInput!]!) {
  mutation: createAssetDesign(payload: $payload) { 
    id
    name
  }
}
